    55	// Formats the table as a SQL CREATE TABLE statement.
    56	impl Display for Table {
    57	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    58	        /// Formats an identifier as valid SQL, quoting it if necessary.
    59	        fn format_ident(ident: &str) -> String {
    60	            match is_ident(ident) {
    61	                true => ident.to_string(),
    62	                false => format!("\"{}\"", ident.replace('\"', "\"\"")),
    63	            }
    64	        }
    65	
    66	        writeln!(f, "CREATE TABLE {} (", format_ident(&self.name))?;
    67	        for (i, column) in self.columns.iter().enumerate() {
    68	            write!(f, "  {} {}", format_ident(&column.name), column.datatype)?;
    69	            if i == self.primary_key {
    70	                write!(f, " PRIMARY KEY")?;
    71	            } else if !column.nullable {
    72	                write!(f, " NOT NULL")?;
    73	            }
    74	            if let Some(default) = &column.default {
    75	                write!(f, " DEFAULT {default}")?;
    76	            }
    77	            if i != self.primary_key {
    78	                if column.unique {
    79	                    write!(f, " UNIQUE")?;
    80	                }
    81	                if column.index {
    82	                    write!(f, " INDEX")?;
    83	                }
    84	            }
    85	            if let Some(reference) = &column.references {
    86	                write!(f, " REFERENCES {reference}")?;
    87	            }
    88	            if i < self.columns.len() - 1 {
    89	                write!(f, ",")?;
    90	            }
    91	            writeln!(f)?;
    92	        }
    93	        write!(f, ")")
    94	    }
    95	}
